.gzp-desk{
          fundal:
            gradient radial (120% 70% la 50% 0%, rgba (214,178,110,.05), transparent 58%),
            gradient radial(130% 100% la 50% 108%, rgba(0,0,0,.34), transparent 62%),
            /* granul lemnului — distanțat larg și neregulat (linii de păr vechi
               Părea ca o catifea) */
            repetare-gradient-liniar (92 de grade,
              rgba(0,0,0,.13) 0 3px,
              transparent 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              transparent 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparent 43px 74px),
            /* îmbinări ale plăcilor */
            repetare-gradient-liniar (90 de grade,
              rgba(0,0,0,.42) 0 2px,
              transparent 2px 148px),
            gradient-liniar(180deg, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-sub{
          poziție: absolută;
          inserare: 0;
          fundal: liniar-gradient(180deg, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), inset 0 0 0 1px rgba(120,90,36,.2);
          transformare: rotire(-1.15deg) translateY(5px);
        }
        .gzp-sub--2{
          fundal: liniar-gradient(180deg, #e1d2ab 0%, #cfbd90 100%);
          transform: rotire(.85deg) translateY(9px);
        }
